fn stmt(&mut self, s: &Stmt) {
    self.detached = None;
    self.set_live(s);

// Store sources into place `dst` at depth `dd`: dst@(dd + k) is src's value at depth k. A source taken
// out of its container by pop() is no longer in the container, so the direct edge to the container is
// not made (the value's concrete aliases still are, through the closure below).
fn store(&mut self, dst: &Pl, dd: u8, srcs: &[Src]) {
    for (p, dp, dv) in srcs {
        // the value at depth dv is p@dp; that is dst@(dd+dv)
        if self.detached.as_ref() != Some(&(*p, *dp)) {
            self.add_edge(dst, add_d(dd, *dv), p, *dp);
        }
        // Ext is no object: two values from the unknown are not one list
        if matches!(p, Pl::Ext) {
            continue;
        }
        // dst now shares with everything p shares with (closure)
        for (q, dq, dpp) in self.partners(p) {
            if *dp >= dpp {
                self.add_edge(dst, add_d(add_d(dd, *dv), 0), &q, add_d(dq, dp - dpp));
            } else {
                self.add_edge(dst, add_d(add_d(dd, *dv), dpp - dp), &q, dq);
            }
        }
    }
    self.detached = None;
}

